// Carry forward context for downstream nodes
const init = $('Initialize Parameters').first().json;
const project = $('Upsert Project').first().json;
const job = $json;
return [{ json: { ...init, projectId: project.id, projectSlug: project.slug, projectName: project.name, jobId: job.id, jobStage: job.stage } }];

// Normalize rows from Postgres
const items = $input.all();
if (!items.length) return [{ json: { rows: [] } }];
const rows = items.map(i => i.json);
return [{ json: { rows } }];

// Determine if we have an existing BRD
const rows = Array.isArray($json.rows) ? $json.rows : [];
const first = rows[0] || null;
const brd = first && typeof first.content === 'object' ? first.content : null;
const hasBrd = !!(brd && brd.type === 'brd' && brd.title && brd.executiveSummary);

return hasBrd
  ? [{ json: { hasBrd: true, brdFromDb: brd } }]
  : [{ json: { hasBrd: false } }];

